import{_ as t,o,c as s,ag as c}from"./chunks/framework.D5hoimZQ.js";const g=JSON.parse('{"title":"科学日报 · 2026-10-09（量子物理）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/quantum-physics/science-daily-2026-10-09.md","filePath":"topics/quantum-physics/science-daily-2026-10-09.md"}'),i={name:"topics/quantum-physics/science-daily-2026-10-09.md"};function n(a,e,r,d,l,u){return o(),s("div",null,[...e[0]||(e[0]=[c('<h1 id="科学日报-·-2026-10-09-量子物理" tabindex="-1">科学日报 · 2026-10-09（量子物理） <a class="header-anchor" href="#科学日报-·-2026-10-09-量子物理" aria-label="Permalink to &quot;科学日报 · 2026-10-09（量子物理）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-09.md</code> — 第32期</p></blockquote><hr><h2 id="晶圆级低对称石墨烯莫尔超晶格-做出集成量子整流器-science" tabindex="-1">晶圆级低对称石墨烯莫尔超晶格，做出集成量子整流器（Science） <a class="header-anchor" href="#晶圆级低对称石墨烯莫尔超晶格-做出集成量子整流器-science" aria-label="Permalink to &quot;晶圆级低对称石墨烯莫尔超晶格，做出集成量子整流器（Science）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-09.md</code> ｜ DOI: 10.1126/science.aeh3915</p></blockquote><ul><li>背景：<strong>低对称材料</strong>能解锁高对称体系中因晶体对称性约束而被&quot;禁止&quot;的丰富<strong>贝里曲率</strong>物理与反常输运（如非线性霍尔效应），但现有方法依赖<strong>外场或复杂异质堆叠</strong>，难以规模化集成。</li><li>方法：<strong>表面预熔工程</strong>——在锗(110) [Ge(110)] 上受控预熔形成条纹状表面图案，把其上石墨烯的对称性从 <strong>D₆ₕ 降到 C₁ᵥ</strong>，得到<strong>晶圆级低对称石墨烯</strong>。</li><li>数据：室温下非线性霍尔电导约 <strong>11 μm·V⁻¹·Ω⁻¹</strong>；第一性原理计算归因于石墨烯狄拉克锥与杂化锗带形成的**&quot;过倾&quot;有质量狄拉克锥**。</li><li>器件：集成的非线性霍尔整流器可从射频输入产生 <strong>&gt;20 mV</strong> 输出，驱动商用升压器与 LED → 一条与 <strong>CMOS 兼容</strong>的晶圆级<strong>非线性量子器件</strong>路线。</li><li>洞察：用衬底&quot;打印&quot;对称性，把本来需要外场/魔角堆叠才能得到的量子输运现象<strong>工程化到晶圆尺度</strong>。与本库&quot;用几何/结构而非外场来编程物性&quot;母题（莫尔、超晶格）一脉相承——<strong>对称性是可按需剪裁的设计变量</strong>。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/quantum-physics/index.md</code> ｜ 第32期 科学板块</p></blockquote><p>关键词：低对称石墨烯、莫尔超晶格、表面预熔、Ge(110)、贝里曲率、非线性霍尔效应、有质量狄拉克锥、量子整流器、CMOS 兼容、晶圆级 关联：<code>topics/quantum-physics/science-daily-2026-10-08.md</code>（前一日：钍-229 核光钟——同为&quot;宏观可运行平台上的量子/精密器件&quot;）、<code>topics/physics/quantum-computing-deep.md</code>、<code>topics/physics/advanced-materials-deep.md</code>（对称性/拓扑与器件化的另一条线）</p>',9)])])}const m=t(i,[["render",n]]);export{g as __pageData,m as default};
